import java.text.NumberFormat;
import java.util.Locale;

public class Numbers {
    public static void main(String[] args) {
        double d = 1234.5678;
        String a = NumberFormat.getNumberInstance(Locale.US).format(d);
        String b = NumberFormat.getIntegerInstance(Locale.US).format(d);
        String c = NumberFormat.getNumberInstance(Locale.GERMANY).format(d);
        System.out.println(a + " | " + b + " | " + c);
    }
}

